from mk import *
from lib import fbd
STRICT["on"] = True

def fig():
    g = Fig(560, 220, "גוף במסה m מחליק במהירות קבועה במורד מישור משופע שזווית נטייתו תטא")
    g.poly([(60, 190), (480, 190), (60, 60)], fill="var(--d-fill)"); g.ground(40, 500, 190)
    g.angle(480, 190, 50, 180 - 17.2, 180, "θ", lr=66)
    g.block(230, 120, 44, 28, "m", angle=-17.2)
    g.arrow(258, 130, 310, 146, "v", lx=318, ly=152, anchor="start")
    return g

A = 25
def slope(forces, pos, note, alt):
    return lambda: fbd(forces, alt, positive=pos, body="block", tilt=-A, surface="below", note=note)

E(id="bagrut-2012-q2", year=2012, label="2012 שאלה 2", topic="dynamics", sub="dyn-incline", diff=4, fig=fig,
  stem=r"גוף שמסתו $m$ מחליק במהירות קבועה במורד מישור משופע בזווית $\theta$. בכל הסעיפים ענו בעזרת $m$, $v_0$, $\theta$, $t$, $F$ ו-$g$, לפי הצורך.",
  parts=[
    P("א", r"שרטטו תרשים של הכוחות על הגוף, ורשמו מה כל כוח. מה הכוח השקול על הגוף? הסבירו.", OPEN, ["fbd", "principle"], [
        X(r"השאלה לא קבעה כיוון. בוחרים את כיוון התנועה, במורד המישור, כחיובי."),
        D(r"תרשים הכוחות על הגוף כשהוא מחליק במורד", slope([("mg", -90, 1.0), ("N", 90 - A, 0.9), ("fₖ", 180 - A, 0.42)], -A, "מחליק במורד",
            "תרשים כוחות על הגוף: כוח הכובד כלפי מטה, הכוח הנורמלי ניצב למישור, וחיכוך קינטי במעלה המישור. הכיוון החיובי במורד המישור")),
        S(r"משוואת כוחות בניצב למישור", r"בכיוון הזה הגוף לא זז", r"N - mg\cos\theta = 0 \;\Rightarrow\; N = mg\cos\theta", eq=r"\Sigma\vec F = m\vec a"),
        S(r"משוואת כוחות לאורך המישור", r"המהירות קבועה, ולכן אין תאוצה. בכיוון החיובי רכיב הכובד, ונגדו החיכוך", r"mg\sin\theta - f_k = 0 \;\Rightarrow\; f_k = mg\sin\theta"),
        S(r"הכוח השקול", r"אין תאוצה, ולכן הכוח השקול אפס", r"\Sigma F = 0"),
        S(r"מקדם החיכוך", r"מחלקים את החיכוך בכוח הנורמלי", r"\mu_k = \frac{mg\sin\theta}{mg\cos\theta} = \tan\theta", eq=r"f_k = \mu_k N"),
    ], r"כובד, נורמלי וחיכוך. הכוח השקול אפס, ומכאן $\mu_k = \tan\theta$"),
    P("ב", r"הגוף נע במעלה המישור, במהירות התחלתית $v_0$ שמקבילה למישור. בשלב מסוים הוא נעצר ונשאר במקום. הסבירו מדוע הגוף לא מחליק למטה אחרי שהוא נעצר.", OPEN, ["fbd", "principle"], [
        D(r"תרשים הכוחות על הגוף כשהוא עומד", slope([("mg", -90, 1.0), ("N", 90 - A, 0.9), ("fₛ", 180 - A, 0.42)], -A, "עומד במקום",
            "תרשים כוחות על הגוף כשהוא עומד: כוח הכובד, הכוח הנורמלי, וחיכוך סטטי במעלה המישור. הכיוון החיובי במורד המישור")),
        S(r"כדי להתחיל לנוע", r"רכיב הכובד שלאורך המישור צריך להיות גדול מהחיכוך הסטטי המרבי", r"mg\sin\theta > \mu_s mg\cos\theta\ ?", eq=r"f_s \le \mu_s N"),
        S(r"משווים", r"מקדם החיכוך הסטטי תמיד לפחות כמו הקינטי, ומצאנו שהקינטי שווה לטנגנס של הזווית", r"\mu_s \ge \mu_k = \tan\theta \;\Rightarrow\; mg\sin\theta \le \mu_s mg\cos\theta"),
    ], r"רכיב הכובד לא גדול מהחיכוך הסטטי המרבי, כי $\mu_s \ge \mu_k = \tan\theta$"),
    P("ג", r"איזה מרחק לאורך המישור עובר הגוף בזמן שהוא עולה?", choice([r"$\frac{v_0^2}{4g\sin\theta}$", r"$\frac{v_0^2}{2g\sin\theta}$", r"$\frac{v_0^2}{2g}$", r"$\frac{v_0^2}{4g\cos\theta}$"], 0), ["fbd", "principle", "algebra"], [
        X(r"עכשיו בוחרים את כיוון התנועה, במעלה המישור, כחיובי. החיכוך נגד התנועה, כלומר במורד."),
        D(r"תרשים הכוחות על הגוף כשהוא עולה", slope([("mg", -90, 1.0), ("N", 90 - A, 0.9), ("fₖ", -A, 0.42)], 180 - A, "עולה",
            "תרשים כוחות על הגוף כשהוא עולה: כוח הכובד, הכוח הנורמלי, וחיכוך קינטי במורד המישור, נגד התנועה. הכיוון החיובי במעלה המישור")),
        S(r"משוואת כוחות לאורך המישור", r"בכיוון החיובי לא פועל אף כוח. נגדו רכיב הכובד והחיכוך", r"0 - mg\sin\theta - f_k = ma", eq=r"\Sigma\vec F = m\vec a"),
        S(r"מציבים את החיכוך", r"החיכוך הקינטי הוא מקדם החיכוך כפול הכוח הנורמלי מסעיף א", r"f_k = \mu_k N = \mu_k mg\cos\theta \;\Rightarrow\; -mg\sin\theta - \mu_k mg\cos\theta = ma"),
        S(r"מחלקים את משוואת הכוחות במסה", r"ומציבים את מקדם החיכוך מסעיף א. שני האיברים שווים", r"a = -(g\sin\theta + \tan\theta \cdot g\cos\theta) = -2g\sin\theta"),
        S(r"משוואת המהירות בלי זמן", r"עד שהגוף נעצר", r"0^2 = v_0^2 + 2(-2g\sin\theta)\,\Delta x", eq=r"v^2 = v_0^2 + 2a(x - x_0)"),
        S(r"מבודדים את המרחק", r"מעבירים אגפים ומחלקים", r"\Delta x = \frac{v_0^2}{4g\sin\theta}"),
    ], r"$\Delta x = \frac{v_0^2}{4g\sin\theta}$", key=r"Δx = −v0²/(4g·sinθ)"),
    P("ד1", r"אחרי שהגוף נעצר, מפעילים עליו במשך $t$ שניות כוח קבוע $F$, מקביל למישור, והגוף מתחיל לנוע במורד. מה גודל המהירות של הגוף בסוף פרק הזמן $t$? (הגוף לא מגיע לתחתית המישור בזמן הזה.)", choice([r"$v = \frac{F}{m}t$", r"$v = \left(\frac{F}{m} + g\sin\theta\right)t$", r"$v = \left(\frac{F}{m} - g\sin\theta\right)t$", r"$v = \frac{F}{2m}t$"], 0), ["fbd", "principle"], [
        X(r"הכיוון החיובי שוב במורד המישור, כיוון התנועה."),
        D(r"תרשים הכוחות על הגוף בזמן שהכוח פועל", slope([("mg", -90, 1.0), ("N", 90 - A, 0.9), ("fₖ", 180 - A, 0.42), ("F", -A, 0.6, 16)], -A, "הכוח F פועל",
            "תרשים כוחות על הגוף: כוח הכובד, הכוח הנורמלי, חיכוך קינטי במעלה המישור, והכוח F במורד המישור. הכיוון החיובי במורד המישור")),
        S(r"משוואת כוחות לאורך המישור", r"בכיוון החיובי הכוח ורכיב הכובד. נגדם החיכוך. רכיב הכובד והחיכוך שווים, לפי סעיף א, ולכן מתבטלים", r"F + mg\sin\theta - mg\sin\theta = ma", eq=r"\Sigma\vec F = m\vec a"),
        S(r"מחלקים את משוואת הכוחות במסה", r"נשאר רק הכוח", r"a = \frac{F}{m}"),
        S(r"משוואת המהירות", r"הגוף יוצא ממנוחה", r"v = 0 + \frac{F}{m}\,t", eq=r"v = v_0 + at"),
    ], r"$v = \frac{F}{m}t$", key=r"v=(F/m)t"),
    P("ד2", r"האם הגוף יגיע לתחתית המישור במהירות שמצאתם בסעיף ד1? נמקו.", choice(["כן", "לא"], 0), ["principle"], [
        S(r"אחרי שהכוח מפסיק", r"שוב רכיב הכובד והחיכוך מתבטלים, כמו בסעיף א. הכוח השקול אפס, והמהירות נשארת קבועה", r"mg\sin\theta - f_k = 0 \;\Rightarrow\; v = \text{const}", eq=r"\Sigma\vec F = m\vec a"),
    ], r"כן: אחרי שהכוח מפסיק הכוח השקול אפס, והמהירות נשארת קבועה", key=r"כן"),
  ],
  concepts=["מישור משופע", "חיכוך קינטי וסטטי", "מהירות קבועה", "ביטוי באמצעות פרמטרים"],
  summary=r"גוף שגולש במהירות קבועה מגלה ש-$\mu_k = \tan\theta$. מזה: למה הוא נשאר במקום אחרי עצירה, כמה הוא עולה, ומה עושה כוח נוסף.",
  review="הנחה שלי.\nבסעיפים ג ו-ד1 התלמיד בוחר את הביטוי הנכון מתוך ארבעה. במקור סעיף ד הוא (1) ו-(2), וכך גם אצלנו.\nמה לבדוק: רק לאשר.")
